arguments.file_text:
@* Single message with author, timestamp, content, reactions, and hover actions *@

<div class="message-card @(IsThreadStarter ? "thread-starter" : "")"
     @onmouseenter="() => _showActions = true"
     @onmouseleave="OnMouseLeave">
    <div class="message-header">
        <span class="message-author">@Message.Author</span>
        <span class="message-time" title="@Message.SentAt.ToString("f")">@FormatRelativeTime(Message.SentAt)</span>
        @if (_showActions)
        {
            <span class="message-actions">
                <button class="btn btn-outline-secondary btn-sm action-btn" @onclick="() => OnOpenThread.InvokeAsync(Message.Id)" title="Reply in thread">
                    💬
                </button>
                <button class="btn btn-outline-secondary btn-sm action-btn" @onclick="ToggleEmojiPicker" title="Add reaction">
                    😀
                </button>
            </span>
        }
    </div>

    <div class="message-content">@Message.Content</div>

    @if (Message.Reactions is { Count: > 0 })
    {
        <div class="reaction-row">
            @foreach (var reaction in Message.Reactions)
            {
                <button class="reaction-badge" @onclick="() => OnReact.InvokeAsync((Message.Id, reaction.Emoji))"
                        title="@string.Join(", ", reaction.Users)">
                    @reaction.Emoji @reaction.Users.Count
                </button>
            }
        </div>
    }

    @if (IsThreadStarter && ReplyCount > 0)
    {
        <button class="thread-link" @onclick="() => OnOpenThread.InvokeAsync(Message.Id)">
            @ReplyCount @(ReplyCount == 1 ? "reply" : "replies")
        </button>
    }

    @if (_showEmojiPicker)
    {
        <EmojiPicker OnEmojiSelected="HandleEmojiSelected" />
    }
</div>

@code {
    [Parameter, EditorRequired] public Message Message { get; set; } = default!;
    [Parameter] public bool IsThreadStarter { get; set; }
    [Parameter] public int ReplyCount { get; set; }
    [Parameter, EditorRequired] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter, EditorRequired] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }

    private bool _showActions;
    private bool _showEmojiPicker;

    private void OnMouseLeave()
    {
        _showActions = false;
        _showEmojiPicker = false;
    }

    private void ToggleEmojiPicker() => _showEmojiPicker = !_showEmojiPicker;

    private async Task HandleEmojiSelected(string emoji)
    {
        _showEmojiPicker = false;
        await OnReact.InvokeAsync((Message.Id, emoji));
    }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt;
        if (diff.TotalSeconds < 60) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        if (diff.TotalDays < 7) return $"{(int)diff.TotalDays}d ago";
        return sentAt.ToString("MMM d, yyyy");
    }
}

@* Collapsible thread panel on the right *@

<div class="thread-panel">
    <div class="thread-header">
        <h6>Thread</h6>
        <button class="btn btn-sm btn-outline-secondary" @onclick="OnClose" title="Close thread">✕</button>
    </div>

    @if (RootMessage is not null)
    {
        <div class="thread-root-quote">
            <MessageCard Message="RootMessage"
                         IsThreadStarter="false"
                         OnOpenThread="NoOp"
                         OnReact="OnReact" />
        </div>

        <hr />

        <div class="thread-messages">
            @foreach (var reply in ThreadMessages)
            {
                <MessageCard Message="reply"
                             IsThreadStarter="false"
                             OnOpenThread="NoOp"
                             OnReact="OnReact" />
            }
        </div>

        <MessageInput Placeholder="Reply in thread…"
                      ButtonLabel="Reply"
                      OnSubmit="OnReply" />
    }
</div>

@code {
    [Parameter, EditorRequired] public Message? RootMessage { get; set; }
    [Parameter, EditorRequired] public List<Message> ThreadMessages { get; set; } = [];
    [Parameter, EditorRequired] public EventCallback OnClose { get; set; }
    [Parameter, EditorRequired] public EventCallback<string> OnReply { get; set; }
    [Parameter, EditorRequired] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }

    private static readonly EventCallback<int> NoOp = default;
}

@* Main message area: channel header, scrollable messages, input *@
@inject IJSRuntime JS

<div class="message-area">
    <div class="message-area-header">
        <h5># @Channel?.Name</h5>
        @if (!string.IsNullOrEmpty(Channel?.Description))
        {
            <span class="channel-description-header">@Channel!.Description</span>
        }
    </div>

    <div class="message-list" id="message-list-scroll" @onscroll="HandleScroll">
        @if (IsLoadingMore)
        {
            <div class="text-center p-2"><em>Loading older messages…</em></div>
        }
        @foreach (var message in Messages)
        {
            var threadInfo = ThreadSummaries.FirstOrDefault(t => t.RootMessageId == message.Id);
            <MessageCard Message="message"
                         IsThreadStarter="@(threadInfo is not null)"
                         ReplyCount="@(threadInfo?.ReplyCount ?? 0)"
                         OnOpenThread="OnOpenThread"
                         OnReact="OnReact" />
        }
    </div>

    <MessageInput Placeholder="@($"Message #{Channel?.Name}…")"
                  ButtonLabel="Send"
                  OnSubmit="OnSendMessage" />
</div>

@code {
    [Parameter, EditorRequired] public Channel? Channel { get; set; }
    [Parameter, EditorRequired] public List<Message> Messages { get; set; } = [];
    [Parameter, EditorRequired] public List<ThreadSummary> ThreadSummaries { get; set; } = [];
    [Parameter] public bool IsLoadingMore { get; set; }
    [Parameter, EditorRequired] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter, EditorRequired] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter, EditorRequired] public EventCallback<string> OnSendMessage { get; set; }
    [Parameter, EditorRequired] public EventCallback OnLoadMore { get; set; }

    private async Task HandleScroll()
    {
        var scrollTop = await JS.InvokeAsync<double>("eval", "document.getElementById('message-list-scroll').scrollTop");
        if (scrollTop < 50 && !IsLoadingMore)
        {
            await OnLoadMore.InvokeAsync();
        }
    }
}

