arguments.file_text:
::deep .chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}

/* ── Channel Sidebar ── */

::deep .channel-sidebar {
    width: 260px;
    min-width: 260px;
    background: #2c2f33;
    color: #dcddde;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #202225;
}

::deep .sidebar-header {
    padding: 16px;
    border-bottom: 1px solid #202225;
}

::deep .sidebar-header h5 {
    margin: 0;
    color: #fff;
    font-size: 1rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.04em;
}

::deep .channel-list {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
}

::deep .channel-item {
    padding: 6px 16px;
    cursor: pointer;
    border-radius: 4px;
    margin: 0 8px;
    transition: background 0.15s;
}

::deep .channel-item:hover {
    background: #35393f;
}

::deep .channel-item.active {
    background: #40444b;
    color: #fff;
}

::deep .channel-name-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

::deep .channel-name {
    font-weight: 600;
    font-size: 0.95rem;
}

::deep .unread-badge {
    font-size: 0.7rem;
    padding: 2px 6px;
    border-radius: 10px;
}

::deep .channel-desc {
    font-size: 0.75rem;
    color: #8e9297;
    margin-top: 2px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

/* ── Main + Thread Container ── */

::deep .main-and-thread {
    flex: 1;
    display: flex;
    min-width: 0;
}

/* ── Message Area ── */

::deep .message-area {
    flex: 1;
    display: flex;
    flex-direction: column;
    min-width: 0;
    background: #36393f;
    color: #dcddde;
}

::deep .message-area-header {
    padding: 12px 20px;
    border-bottom: 1px solid #202225;
    background: #36393f;
}

::deep .message-area-header h5 {
    margin: 0;
    color: #fff;
    font-size: 1rem;
    font-weight: 700;
}

::deep .channel-description-header {
    font-size: 0.8rem;
    color: #8e9297;
}

::deep .message-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px 20px;
}

/* ── Message Card ── */

::deep .message-card {
    padding: 8px 12px;
    border-radius: 4px;
    margin-bottom: 4px;
    position: relative;
    transition: background 0.1s;
}

::deep .message-card:hover {
    background: #32353b;
}

::deep .message-header {
    display: flex;
    align-items: center;
    gap: 8px;
    margin-bottom: 2px;
}

::deep .message-author {
    font-weight: 700;
    color: #fff;
    font-size: 0.95rem;
}

::deep .message-time {
    font-size: 0.75rem;
    color: #72767d;
}

::deep .message-actions {
    margin-left: auto;
    display: flex;
    gap: 4px;
}

::deep .action-btn {
